// Regenerates js/export-css.js (a string copy of css/app.css used by offline exports; file:// pages cannot fetch CSS).
// Run: node tools-build-css.js
const fs = require('fs');
const css = fs.readFileSync(__dirname + '/css/app.css', 'utf8');
fs.writeFileSync(__dirname + '/js/export-css.js',
  '/* Generated by tools-build-css.js from css/app.css. Do not edit by hand. */\n(function (G) { G.__css = ' + JSON.stringify(css) + '; })(typeof window !== \'undefined\' ? (window.Glassbox = window.Glassbox || {}) : (globalThis.Glassbox = globalThis.Glassbox || {}));\n');
console.log('wrote js/export-css.js (' + css.length + ' chars)');
